import { Menu,MenuItem } from "../Types";

export default function constructMenu(menu: Menu) {
    return (
        <ul className="d-flex flex-row text-white list-style-type-none p-0 m-0">
            {menu.items.map((item, index) => (
                <li key={index} className="w-100 font-leading-2 px-1">
                    {item.label}
                    {item.menu && constructMenu(item.menu)}
                </li>
            ))}
        </ul>
    )
}